class Solution {
public:
    string removeOccurrences(string s, string part) {
        string res = "";
        int m = part.length();
        for (char ch : s) {
            res.push_back(ch);
            if (res.length() >= m && res.substr(res.length() - m, m) == part) {
                res.erase(res.length() - m, m);
            }
        }
        return res;
    }
};

class Solution {
    public String removeOccurrences(String s, String part) {
        StringBuilder sb = new StringBuilder();
        int m = part.length();
        for (char ch : s.toCharArray()) {
            sb.append(ch);
            if (sb.length() >= m && sb.substring(sb.length() - m).equals(part)) {
                sb.delete(sb.length() - m, sb.length());
            }
        }
        return sb.toString();
    }
}

var removeOccurrences = function(s, part) {
  const stack = [];
  const m = part.length;
  for (const ch of s) {
    stack.push(ch);
    if (stack.length >= m && stack.slice(stack.length - m).join('') === part) {
      stack.length -= m;
    }
  }
  return stack.join('');
};
